          </div>
          <input 
            type="range" min="0" max="100" step="20" 
            value={settings.beauty.smoothSkin} 
            onChange={(e) => onAiBeautyChange('smoothSkin', Number(e.target.value))} 
            className="w-full" 
          />
      </div>

      {/* 3. LIPSTICK */}
      <div className="space-y-4 pt-4 border-t border-gray-200 dark:border-gray-700">
