            <span className="text-[11px] font-black text-gray-900 dark:text-white uppercase tracking-widest">{t('editor.makeup.lipstick', config)}</span>
            <span className="text-xs font-black text-pink-600 dark:text-pink-400">{settings.beauty.lipstickIntensity}%</span>
         </div>
